  "Ask at 3 a.m. Samsoom already knows the shelf.": "रात 3 बजे पूछें। Samsoom पहले से शेल्फ़ जानता है।",
  "Samsoom knows our catalogue, grades, hours and shipping. It finds the part, explains the grade, and hands you to a person on WhatsApp the second you need one.": "Samsoom हमारा कैटलॉग, ग्रेड, समय और शिपिंग जानता है। वह पार्ट ढूंढता है, ग्रेड समझाता है और ज़रूरत पड़ते ही WhatsApp पर किसी व्यक्ति से जोड़ता है।",
