  "Original or Service Pack for the best result, OLED for value, Incell when budget comes first.": "बेहतरीन नतीजे के लिए Original या Service Pack, वैल्यू के लिए OLED, बजट पहले हो तो Incell।",
  "Original or Service Pack for the best result. OLED is great value. Incell when budget comes first. Every grade is labelled on your order.": "बेहतरीन नतीजे के लिए Original या Service Pack। OLED बढ़िया वैल्यू है। बजट पहले हो तो Incell। हर ग्रेड आपके ऑर्डर पर लिखा होता है।",
  "Yes. We ship every day to the Middle East, Africa, Europe and Asia. Tracked, packed by hand, quoted with your order.": "हां। हम हर दिन मध्य पूर्व, अफ्रीका, यूरोप और एशिया भेजते हैं। ट्रैक, हाथ से पैक, ऑर्डर के साथ कोटेशन।",
  "Yes. We ship worldwide, mainly to the Middle East, Africa, Europe and Asia. Tracked and securely packed; shipping is quoted with your order.": "हां। हम दुनिया भर में भेजते हैं, मुख्य रूप से मध्य पूर्व, अफ्रीका, यूरोप और एशिया। ट्रैक और सुरक्षित पैक; शिपिंग ऑर्डर के साथ बताई जाती है।",
  "Our bench in Deira fixes screens, batteries, charging ports and board faults. Try the estimator for a price range.": "देरा में हमारी बेंच स्क्रीन, बैटरी, चार्जिंग पोर्ट और बोर्ड ठीक करती है। कीमत की रेंज के लिए एस्टिमेटर आज़माएं।",
