  "Approved refunds are made to the original payment method within 14 days. Delivery costs are not refunded unless we sent the wrong or a faulty part.": "मंज़ूर रिफ़ंड 14 दिनों में मूल भुगतान तरीके पर किए जाते हैं। डिलीवरी शुल्क वापस नहीं होता, जब तक हमने गलत या खराब पार्ट न भेजा हो।",
