  "Ask for a copy of the data we hold about you, a correction, or the deletion of your account. We answer within 30 days.": "हमारे पास मौजूद अपने डेटा की प्रति, सुधार या अकाउंट हटाने का अनुरोध करें। हम 30 दिनों में जवाब देते हैं।",
  "Ask for a copy, a correction or deletion of your data, or object to its use, using the privacy form on the contact page. We answer within 30 days, in line with the UAE personal data protection law.": "संपर्क पेज पर प्राइवेसी फ़ॉर्म से अपने डेटा की प्रति, सुधार या हटाने का अनुरोध करें, या उसके इस्तेमाल पर आपत्ति करें। हम UAE के निजी डेटा संरक्षण कानून के अनुसार 30 दिनों में जवाब देते हैं।",
