  "No separate catalogue, no price lists to ask for. Sign in and the shop shows the trade price next to the retail price on every part, in every grade.": "न अलग कैटलॉग, न माँगनी पड़ें प्राइस लिस्ट। साइन इन करें और दुकान हर पार्ट पर, हर ग्रेड में, रिटेल के साथ ट्रेड कीमत दिखाती है।",
  "Not on the list? We ship almost anywhere: ask us.": "सूची में नहीं? हम लगभग हर जगह भेजते हैं: पूछें।",
  "Not sure it is the right one? Send us your model number on WhatsApp and we will check it for you.": "पक्का नहीं कि सही है? WhatsApp पर मॉडल नंबर भेजें, हम जाँच देंगे।",
