  "Nothing in these terms limits your rights under UAE consumer protection law. Apart from those rights, our liability for a part is limited to repairing, replacing or refunding that part.": "इन शर्तों में कुछ भी UAE उपभोक्ता संरक्षण कानून के तहत आपके अधिकार सीमित नहीं करता। उन अधिकारों के अलावा, किसी पार्ट के लिए हमारी ज़िम्मेदारी उसकी मरम्मत, बदलने या रिफ़ंड तक सीमित है।",
