  "One for customers, one for suppliers, and one we give to our most loyal customers. Each is earned its own way, and each lives in your account.": "एक ग्राहकों के लिए, एक सप्लायरों के लिए, और एक जो हम अपने सबसे वफ़ादार ग्राहकों को देते हैं। हर एक का अपना तरीका है, और सब आपके अकाउंट में रहते हैं।",
