  "Only account holders can rate parts, and reviews of parts you bought are marked \"verified purchase\". Reviews must be honest and about the part. We remove reviews that are abusive, off-topic, contain personal data or advertise other businesses.": "सिर्फ़ अकाउंट वाले पार्ट रेट कर सकते हैं, और ख़रीदे गए पार्ट के रिव्यू पर “सत्यापित ख़रीद” लिखा होता है। रिव्यू ईमानदार और पार्ट के बारे में होने चाहिए। हम अपमानजनक, विषय से हटकर, निजी जानकारी वाले या दूसरे व्यवसायों का विज्ञापन करने वाले रिव्यू हटाते हैं।",
  "Only account holders can rate parts, so every review is from a real customer.": "सिर्फ़ अकाउंट वाले रेट कर सकते हैं, इसलिए हर रिव्यू असली ग्राहक का है।",
