  "Orders, stars, points, companies and your chats with Samsoom, all in one place.": "ऑर्डर, स्टार, पॉइंट, कंपनियाँ और सैमसूम से आपकी चैट, सब एक जगह।",
  "Original (Service Pack) is the part the brand fits. OLED Soft is close to original at a lower price. Incell is a reliable budget LCD. AAA is our best-price grade. Every part is labelled by quality and manufacturer.": "ओरिजिनल (सर्विस पैक) वह पार्ट है जो ब्रांड ख़ुद लगाता है। OLED Soft कम कीमत पर मूल जैसा है। Incell भरोसेमंद बजट LCD है। AAA हमारा सबसे सस्ता ग्रेड है। हर पार्ट पर गुणवत्ता और निर्माता लिखा है।",
  "Original (Service Pack): 6 months. OLED Soft: 3 months. Incell and AAA: 1 month. Other parts: as stated on the product. The warranty starts on the invoice date.": "ओरिजिनल (सर्विस पैक): 6 महीने। OLED Soft: 3 महीने। Incell और AAA: 1 महीना। बाकी पार्ट: प्रोडक्ट पर लिखे अनुसार। वारंटी इनवॉइस की तारीख़ से शुरू होती है।",
  "Original / Compatible · up to 6 months": "ओरिजिनल / कम्पैटिबल · 6 महीने तक",
  "Original grade · 3 months": "ओरिजिनल ग्रेड · 3 महीने",
