  "Physical damage (cracks, bends, pressure marks), liquid damage, parts damaged while being fitted by a third party, parts with removed or altered labels, and normal wear such as battery capacity loss within specification.": "भौतिक नुकसान (दरार, मुड़ना, दबाव के निशान), तरल से नुकसान, किसी तीसरे द्वारा लगाते समय खराब हुए पार्ट, हटाए या बदले गए लेबल वाले पार्ट, और सामान्य घिसाव जैसे स्पेसिफ़िकेशन के भीतर बैटरी क्षमता घटना।",
