  "Placing an order is a request to buy. The contract is made when we confirm stock and price to you (by WhatsApp, e-mail or in the shop) and you pay or agree to pay.": "ऑर्डर देना ख़रीदने का अनुरोध है। अनुबंध तब होता है जब हम स्टॉक और कीमत की पुष्टि करते हैं (WhatsApp, ई-मेल या दुकान में) और आप भुगतान करते हैं या करने को सहमत होते हैं।",
