  "The": "यह",
  "The brand’s own part": "ब्रांड का अपना पार्ट",
  "The card for everyone who buys parts or repairs with us. Register online, your first purchase activates it, and every dirham you spend charges it up.": "हमसे पार्ट ख़रीदने या मरम्मत करवाने वाले हर किसी के लिए कार्ड। ऑनलाइन रजिस्टर करें, पहली ख़रीद इसे चालू करती है, और हर दिरहम इसे चार्ज करता है।",
  "The fee follows the price of the part. Our technician may adjust it up or down for the part and the work involved, and always tells you before starting.": "फ़ीस पार्ट की कीमत के हिसाब से है। टेक्नीशियन पार्ट और काम के अनुसार इसे घटा-बढ़ा सकता है, और शुरू करने से पहले हमेशा बताता है।",
  "The fine print,": "बारीक शर्तें,",
  "The part and the fitting fee both count.": "पार्ट और फ़िटिंग फ़ीस दोनों गिने जाते हैं।",
  "The part the brand itself fits, in its service box. Same colors, brightness, touch and battery life as new. Our longest warranty.": "वह पार्ट जो ब्रांड ख़ुद लगाता है, सर्विस बॉक्स में। नए जैसे रंग, चमक, टच और बैटरी लाइफ़। हमारी सबसे लंबी वारंटी।",
  "The part the brand itself fits.": "वह पार्ट जो ब्रांड ख़ुद लगाता है।",
  "The people behind the counter.": "काउंटर के पीछे के लोग।",
  "The phones we stock parts for, and the factories behind every part, so you always know exactly what you are buying.": "जिन फ़ोन के पार्ट हमारे पास हैं, और हर पार्ट के पीछे के कारखाने, ताकि आप हमेशा जानें कि आप क्या ख़रीद रहे हैं।",
  "The whole shop": "पूरी दुकान",
  "These terms are governed by the laws of the Emirate of Dubai and the federal laws of the UAE. The courts of Dubai have jurisdiction.": "ये शर्तें दुबई अमीरात के कानूनों और UAE के संघीय कानूनों से शासित हैं। दुबई की अदालतें अधिकार क्षेत्र रखती हैं।",
  "This site keeps a few things in your browser so it works: your language, your cart, stars and recent searches, whether you have seen Samsoom’s tour, and your sign-in session. We do not use advertising cookies.": "यह साइट काम करने के लिए आपके ब्राउज़र में कुछ चीज़ें रखती है: आपकी भाषा, कार्ट, स्टार और हाल की खोजें, क्या आपने सैमसूम का टूर देखा, और आपका साइन-इन सेशन। हम विज्ञापन कुकी इस्तेमाल नहीं करते।",
  "Three steps to trade prices.": "ट्रेड कीमतों के तीन क़दम।",
