  "Title": "शीर्षक",
  "To be the parts counter repair shops trust most, from Dubai to Madrid and beyond.": "दुबई से मैड्रिड और उससे आगे, रिपेयर दुकानों का सबसे भरोसेमंद पार्ट्स काउंटर बनना।",
  "To sell and deliver parts, run repairs and warranties, approve trade accounts, answer you, keep the accounts required by UAE tax law, and improve the site. We do not sell your data.": "पार्ट बेचने और पहुँचाने, मरम्मत और वारंटी चलाने, ट्रेड अकाउंट मंज़ूर करने, आपको जवाब देने, UAE टैक्स कानून के लिए हिसाब रखने, और साइट बेहतर करने के लिए। हम आपका डेटा नहीं बेचते।",
