  "Walk in any time we are open, or book a time and skip the queue. We confirm on WhatsApp.": "जब हम खुले हों तब आएँ, या समय बुक करके लाइन से बचें। हम WhatsApp पर पक्का करते हैं।",
  "Warranty & quality": "वारंटी और गुणवत्ता",
  "Warranty & returns": "वारंटी और वापसी",
  "Warranty covers faults from the part itself. It does not cover physical or water damage, or parts fitted elsewhere that were damaged while fitting.": "वारंटी पार्ट की अपनी ख़राबी कवर करती है। भौतिक या पानी से नुकसान, या कहीं और लगाते समय ख़राब हुए पार्ट कवर नहीं।",
  "Warranty or return": "वारंटी या वापसी",
  "Warranty policy": "वारंटी नीति",
  "We accept cash and card in the shop, bank transfer, and payment links we send after confirming your order. Orders are released for delivery or collection once paid, unless your trade account has approved credit.": "हम दुकान में नकद और कार्ड, बैंक ट्रांसफ़र, और ऑर्डर पक्का होने के बाद भेजे पेमेंट लिंक लेते हैं। भुगतान के बाद ऑर्डर डिलीवरी या पिकअप के लिए दिए जाते हैं, जब तक आपके ट्रेड अकाउंट को मंज़ूर क्रेडिट न हो।",
  "We book the best route for your parcel: express for urgent parts, air cargo for bulk.": "हम आपके पार्सल का सबसे अच्छा रास्ता बुक करते हैं: ज़रूरी के लिए एक्सप्रेस, थोक के लिए एयर कार्गो।",
  "We check the phone in front of you.": "हम फ़ोन आपके सामने जाँचते हैं।",
  "We confirm on WhatsApp, then send a payment link": "हम WhatsApp पर पक्का करके पेमेंट लिंक भेजते हैं",
  "We help with packing and paperwork, but the shipping cost and the shipper’s terms are between you and your shipper.": "हम पैकिंग और काग़ज़ों में मदद करते हैं, पर शिपिंग की कीमत और शर्तें आपके और आपके शिपर के बीच हैं।",
  "We hire people who like phones, people and getting things exactly right. Openings are samples until the owner publishes real ones.": "हम ऐसे लोग रखते हैं जिन्हें फ़ोन, लोग और सटीक काम पसंद हो। असली पद मालिक के प्रकाशित करने तक ये नमूना हैं।",
  "We opened WhatsApp with your booking; the team confirms the time there.": "हमने आपकी बुकिंग के साथ WhatsApp खोला; टीम वहीं समय पक्का करेगी।",
  "We opened WhatsApp with your request; the team replies there.": "हमने आपके अनुरोध के साथ WhatsApp खोला; टीम वहीं जवाब देगी।",
  "We quote shipping": "हम शिपिंग का कोटेशन देते हैं",
  "We received your application and will be in touch.": "हमें आपका आवेदन मिल गया, हम संपर्क करेंगे।",
  "We received your order. Our team confirms stock, delivery and the final price on WhatsApp, usually within minutes during opening hours.": "हमें आपका ऑर्डर मिल गया। टीम WhatsApp पर स्टॉक, डिलीवरी और अंतिम कीमत पक्की करती है, आमतौर पर खुलने के समय में कुछ ही मिनटों में।",
  "We reply here during opening hours, and by e-mail after.": "हम खुलने के समय यहाँ, और उसके बाद ई-मेल से जवाब देते हैं।",
  "We sent a 6-digit code to": "हमने 6 अंकों का कोड भेजा:",
  "We ship door to door with our partners (such as Sky Dragon, Emirates SkyCargo, UPS and DHL) and quote the price and time before you pay. Duties and taxes in the destination country are paid by the receiver unless agreed otherwise.": "हम अपने पार्टनर (जैसे Sky Dragon, Emirates SkyCargo, UPS और DHL) के साथ दरवाज़े से दरवाज़े भेजते हैं और भुगतान से पहले कीमत और समय बताते हैं। गंतव्य देश के शुल्क और कर प्राप्तकर्ता देता है, जब तक अलग तय न हो।",
  "We ship parts every week to repair shops and traders across the Middle East, Africa, Europe and Asia: door to door with our partners, or with your own shipper.": "हम हर हफ़्ते मध्य पूर्व, अफ़्रीका, यूरोप और एशिया की रिपेयर दुकानों और ट्रेडरों को पार्ट भेजते हैं: हमारे पार्टनर के साथ या आपके अपने शिपर के साथ, दरवाज़े से दरवाज़े।",
  "We ship to 28+ countries every week, door to door, and we can hand your order to your own shipper.": "हम हर हफ़्ते 28+ देशों में दरवाज़े से दरवाज़े भेजते हैं, और आपका ऑर्डर आपके अपने शिपर को सौंप सकते हैं।",
  "We started in 2003 as Syria Tell. In 2020 the shop took the name Sam Electronics, with the same management and the same people behind the counter.": "हमने 2003 में 'सीरिया टेल' के नाम से शुरुआत की। 2020 में दुकान का नाम सैम इलेक्ट्रॉनिक्स हुआ, वही मैनेजमेंट और काउंटर के पीछे वही लोग।",
  "We verify and approve": "हम जाँचते और मंज़ूर करते हैं",
