  "AED 1 = 1 point, on every part and every repair.": "AED 1 = 1 पॉइंट, हर पार्ट और हर मरम्मत पर।",
  "AED 1 = 1 point on every part and repair. Your level rises as your points do.": "AED 1 = 1 पॉइंट हर पार्ट और मरम्मत पर। पॉइंट के साथ आपका लेवल बढ़ता है।",
  "The trade card. Apply online with your trade licence; our management team checks it and activates the card by hand. Your monthly volume sets your level.": "ट्रेड कार्ड। अपने ट्रेड लाइसेंस के साथ ऑनलाइन आवेदन करें; हमारी मैनेजमेंट टीम जाँचकर कार्ड ख़ुद चालू करती है। आपकी मासिक ख़रीद आपका लेवल तय करती है।",
  "estimate": "अनुमान",
  "Newest": "नवीनतम",
  "Everything": "सब कुछ",
  "Yes: the part and the fitting fee both count, AED 1 = 1 point.": "हाँ: पार्ट और फ़िटिंग फ़ीस दोनों गिने जाते हैं, AED 1 = 1 पॉइंट।",
  "From your approved trade orders in the last 30 days. It is reviewed every month; you never drop more than one level at a time.": "पिछले 30 दिनों के मंज़ूर ट्रेड ऑर्डर से। हर महीने समीक्षा होती है; आप एक बार में एक लेवल से ज़्यादा नहीं गिरते।",
  "Send a list on WhatsApp or upload it; we price it the same day.": "WhatsApp पर सूची भेजें या अपलोड करें; हम उसी दिन कीमत बताते हैं।",
