  "Prices in the shop are shown without VAT; 5% UAE VAT is added at checkout and shown on your invoice.": "दुकान में कीमतें VAT के बिना हैं; चेकआउट पर 5% UAE VAT जुड़ता है और आपके इनवॉइस पर दिखता है।",
  "Bring or send it back with the invoice within the warranty. We test it; if it is faulty we replace it or refund you. See the returns policy for the details.": "वारंटी के भीतर इनवॉइस के साथ लाएँ या भेजें। हम जाँचते हैं; ख़राब हो तो बदलते हैं या पैसे लौटाते हैं। विवरण वापसी नीति में।",
  "Cookies": "कुकी",
  "These terms apply to every sale by Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates (\"Sam Electronics\", \"we\"), in the shop, on this website, on WhatsApp or by phone.": "ये शर्तें Sam Electronics L.L.C, अल मुरार, देरा, दुबई, UAE (\"Sam Electronics\", \"हम\") की दुकान, इस वेबसाइट, WhatsApp या फ़ोन पर हर बिक्री पर लागू हैं।",
  "Prices": "कीमतें",
