  "You may ask us to hand your order to your own shipper or cargo agent. We pack it and share the paperwork; the shipping cost and the shipper’s terms are between you and your shipper, and responsibility passes to you when we hand the parcel over.": "आप ऑर्डर अपने शिपर या कार्गो एजेंट को सौंपने को कह सकते हैं। हम पैक करके काग़ज़ देते हैं; शिपिंग कीमत और शर्तें आपके और शिपर के बीच हैं, और पार्सल सौंपते ही ज़िम्मेदारी आपकी हो जाती है।",
  "You can clear them at any time in your browser; the site will simply forget your cart and preferences on that device.": "आप इन्हें कभी भी ब्राउज़र में मिटा सकते हैं; साइट उस डिवाइस पर आपका कार्ट और पसंद भूल जाएगी।",
  "A well-known aftermarket maker with consistent quality and packaging; our usual AAA choice.": "स्थिर गुणवत्ता और पैकिंग वाला जाना-माना आफ़्टरमार्केट निर्माता; हमारी आम AAA पसंद।",
