  "Booked": "बुक हुई",
  "The team updates you on WhatsApp at each step.": "टीम हर कदम पर WhatsApp से आपको बताती है।",
  "Repairs you book on this device appear here with their job ticket.": "इस डिवाइस से बुक की गई रिपेयर अपने जॉब टिकट के साथ यहां दिखती हैं।",
  "Order": "ऑर्डर",
  "Each part’s warranty is on its label and invoice; bring the order number with the part.": "हर पार्ट की वारंटी उसके लेबल और इनवॉइस पर है; पार्ट के साथ ऑर्डर नंबर लाएं।",
  "Repairs are covered from the day you collect the phone. Bring this ticket.": "रिपेयर पर वारंटी फोन लेने के दिन से लागू है। यह टिकट साथ लाएं।",
  "We can’t find that number on this account. Check it, or send it to us on WhatsApp and we look it up.": "इस अकाउंट में यह नंबर नहीं मिला। इसे जांचें या WhatsApp पर भेजें, हम ढूंढ देंगे।",
  "This browser cannot scan codes. Type the number instead.": "यह ब्राउज़र कोड स्कैन नहीं कर सकता। नंबर टाइप करें।",
  "The camera is not available. Type the number instead.": "कैमरा उपलब्ध नहीं है। नंबर टाइप करें।",
  "Warranty check": "वारंटी जांच",
  "Type the order number or the repair job number, or scan the QR on your job ticket.": "ऑर्डर नंबर या रिपेयर जॉब नंबर लिखें, या जॉब टिकट का QR स्कैन करें।",
  "Check": "जांचें",
