  "Quick order: paste part codes, one per line, with a quantity": "क्विक ऑर्डर: पार्ट कोड पेस्ट करें, हर लाइन में एक, मात्रा के साथ",
  "Add all to cart": "सब कार्ट में जोड़ें",
