  "ask for stock": "स्टॉक पूछें",
  "Add a part": "पार्ट जोड़ें",
  "Loading parts…": "पार्ट्स लोड हो रहे हैं…",
  "Orders like this per month": "हर महीने ऐसे ऑर्डर",
  "Everyone pays": "सबके लिए कीमत",
  "You pay with a trade account": "ट्रेड अकाउंट से आपकी कीमत",
  "per order": "प्रति ऑर्डर",
  "a year": "प्रति वर्ष",
  "Sample prices while the shop is set up": "शॉप तैयार होने तक सैंपल कीमतें",
  "Your application": "आपका आवेदन",
  "Approved. Sign in and the shop shows your trade price on every part.": "स्वीकृत। साइन इन करें, शॉप हर पार्ट पर आपकी ट्रेड कीमत दिखाएगी।",
  "We reply by e-mail and WhatsApp, usually within one working day. Sign in with the same e-mail to see the result here.": "हम ई-मेल और WhatsApp से आमतौर पर एक कार्यदिवस में जवाब देते हैं। परिणाम देखने के लिए उसी ई-मेल से साइन इन करें।",
  "TRADE CALCULATOR": "ट्रेड कैलकुलेटर",
  "What would you save?": "आप कितना बचाएंगे?",
  "THE TRADE FLOOR": "ट्रेड फ्लोर",
  "Stock on the floor, by family.": "फ्लोर पर स्टॉक, परिवार के अनुसार।",
