  "Typical times for planning. Every shipment is quoted with its own time and price.": "योजना के लिए अनुमानित समय। हर शिपमेंट का समय और कीमत अलग से बताई जाती है।",
  "CUSTOMS NOTES": "कस्टम्स नोट्स",
