  "Every week, out of Dubai.": "हर हफ्ते, दुबई से।",
  "Planes on the air routes, ships on the sea lanes. Pick a region to see how we ship there.": "हवाई मार्गों पर विमान, समुद्री मार्गों पर जहाज़। क्षेत्र चुनें और देखें हम वहां कैसे भेजते हैं।",
  "SHIPPING QUOTE": "शिपिंग कोटेशन",
  "POINTS SIMULATOR": "पॉइंट्स सिम्युलेटर",
