  "As soon as possible": "जितनी जल्दी हो सके",
  "Estimate": "अनुमान",
  "Show this at the counter. The final price is confirmed after the free check.": "यह काउंटर पर दिखाएं। अंतिम कीमत मुफ्त जांच के बाद तय होती है।",
  "Print": "प्रिंट",
  "Bench now": "बेंच अभी",
  "TAP WHAT IS BROKEN": "जो टूटा है उस पर टैप करें",
  "Point at the part": "पार्ट की ओर इशारा करें",
  "Every layer of the phone opens its repair below, with every grade and the total.": "फोन की हर परत नीचे अपनी रिपेयर खोलती है, हर ग्रेड और कुल के साथ।",
  "Not chosen yet": "अभी नहीं चुना",
  "Check first": "पहले जांच",
  "After the free check": "मुफ्त जांच के बाद",
  "MANUFACTURER": "निर्माता",
  "Pick up to three to compare": "तुलना के लिए तीन तक चुनें",
  "A guide to how the grades usually compare. Each part’s own label and warranty are on its page.": "ग्रेड आमतौर पर कैसे तुलना करते हैं इसकी गाइड। हर पार्ट का लेबल और वारंटी उसके पेज पर है।",
  "FROM FACTORY TO YOUR BENCH": "फैक्टरी से आपकी बेंच तक",
  "Every part has a journey.": "हर पार्ट की एक यात्रा है।",
  "CREATE YOUR ACCOUNT": "अपना अकाउंट बनाएं",
  "MY BENCH · SIGN IN": "मेरी बेंच · साइन इन",
  "Talk to a person": "किसी व्यक्ति से बात करें",
  "Here is a photo of my phone. What does it need?": "यह मेरे फोन की फोटो है। इसे क्या चाहिए?",
  "Thanks for the photo! I can’t look at photos right now, so send it to the team on WhatsApp and they will tell you the part and the price.": "फोटो के लिए धन्यवाद! मैं अभी फोटो नहीं देख सकता, इसे WhatsApp पर टीम को भेजें, वे पार्ट और कीमत बताएंगे।",
  "Thanks for the photo! Send it to the team on WhatsApp and they will tell you the part and the price.": "फोटो के लिए धन्यवाद! इसे WhatsApp पर टीम को भेजें, वे पार्ट और कीमत बताएंगे।",
  "Where do I find my model code?": "मॉडल कोड कहां मिलेगा?",
  "I have my model code: ": "मेरे पास मॉडल कोड है: ",
  "I have it, ask Samsoom": "मिल गया, Samsoom से पूछें",
  "Your photo": "आपकी फोटो",
  "Photo ready to send": "फोटो भेजने के लिए तैयार",
