  "My lists": "मेरी सूचियां",
  "No lists yet. Name one, e.g. “Shop order June”.": "अभी कोई सूची नहीं। एक का नाम रखें, जैसे “जून शॉप ऑर्डर”।",
  "New list name": "नई सूची का नाम",
  "See my lists": "मेरी सूचियां देखें",
  "Request it": "इसका अनुरोध करें",
  "Reviews open once we have confirmed your order of this part, so every review is a verified purchase.": "इस पार्ट का आपका ऑर्डर कन्फर्म होने के बाद रिव्यू खुलते हैं, इसलिए हर रिव्यू वेरिफाइड खरीद है।",
  "Only customers who bought this part can review it, after we confirm their order.": "केवल वे ग्राहक जिन्होंने यह पार्ट खरीदा, ऑर्डर कन्फर्म होने के बाद रिव्यू दे सकते हैं।",
  "Prices and stock shown are test data while the shop is set up": "शॉप तैयार होने तक दिखाई गई कीमतें और स्टॉक टेस्ट डेटा हैं",
  "Quick filters": "क्विक फ़िल्टर",
