  'Everything on this website and in its systems (photos, designs, texts, prices and data) belongs to Sam Electronics and is protected by the copyright laws of the United Arab Emirates, including Federal Decree-Law No. 38 of 2021. A screenshot for your own reference is fine; copying, sharing or publishing it without our written permission is not.': 'इस वेबसाइट और इसके सिस्टम की हर चीज़ (फ़ोटो, डिज़ाइन, टेक्स्ट, कीमतें और डेटा) Sam Electronics की है और UAE के कॉपीराइट कानूनों, जिनमें 2021 का संघीय डिक्री-कानून संख्या 38 शामिल है, से सुरक्षित है। अपने लिए स्क्रीनशॉट ठीक है; हमारी लिखित अनुमति के बिना कॉपी, शेयर या प्रकाशित करना नहीं।',
  'Your connection says you are somewhere else than your device does. Prices, stock and delivery here depend on where you really are, and hiding your location goes against our terms of use. Please switch the VPN off for real prices and delivery times.': 'आपका कनेक्शन आपके डिवाइस से अलग जगह बता रहा है। कीमतें, स्टॉक और डिलीवरी आपकी असली जगह पर निर्भर हैं, और जगह छिपाना हमारी शर्तों के ख़िलाफ़ है। असली कीमतें और समय देखने के लिए VPN बंद करें।',
  'Prices and delivery depend on where you really are. Please switch the VPN off.': 'कीमतें और डिलीवरी आपकी असली जगह पर निर्भर हैं। कृपया VPN बंद करें।',
