  'I can see an IMEI number on the photo. Send it to the team on WhatsApp and they will find the exact model.': 'फ़ोटो में IMEI नंबर दिख रहा है। इसे WhatsApp पर टीम को भेजें, वे सही मॉडल ढूँढ लेंगे।',
  'I looked closely but couldn’t read a model on this photo. A screenshot of Settings → About phone works best, or just tell me the model.': 'मैंने ध्यान से देखा पर इस फ़ोटो में मॉडल नहीं पढ़ पाया। सेटिंग्स → फ़ोन के बारे में का स्क्रीनशॉट सबसे अच्छा है, या बस मॉडल बता दें।',
  'I can read text on photos, but I couldn’t find a model on this one. Try the label on the box, or type the model, and I’ll take it from there.': 'मैं फ़ोटो पर लिखा पढ़ सकता हूँ, पर इसमें मॉडल नहीं मिला। डिब्बे का लेबल आज़माइए या मॉडल लिख दीजिए, बाकी मैं देख लूँगा।',
  'Send me a photo with the camera button: a screenshot of Settings → About phone, or the label on the box, works best. I’ll read the model for you.': 'कैमरा बटन से फ़ोटो भेजें: सेटिंग्स → फ़ोन के बारे में का स्क्रीनशॉट या डिब्बे का लेबल सबसे अच्छा है। मैं मॉडल पढ़ लूँगा।',
  'Settings → About phone → Model.': 'सेटिंग्स → फ़ोन के बारे में → मॉडल।',
  'Settings → About phone → All specs → Model.': 'सेटिंग्स → फ़ोन के बारे में → सभी स्पेसिफ़िकेशन → मॉडल।',
  'Dial *#06# for the IMEI and send it to us: we find the exact model.': 'IMEI के लिए *#06# डायल करें और हमें भेजें: हम सही मॉडल ढूँढ लेंगे।',
