  'Call the shop, message us on WhatsApp or WeChat, or e-mail us. We’re @samelectronics.uae on Instagram, TikTok and Facebook.': 'दुकान पर कॉल करें, WhatsApp या WeChat पर मैसेज करें, या ई-मेल करें। हम Instagram, TikTok और Facebook पर @samelectronics.uae हैं।',
  'Every part has a warranty that depends on the grade:': 'हर पार्ट की वारंटी है जो ग्रेड पर निर्भर करती है:',
  'Tell me the model and the part, like “A54 battery” or “iPhone 13 screen”, and I’ll show the price of each grade.': 'मॉडल और पार्ट बताइए, जैसे “A54 बैटरी” या “iPhone 13 स्क्रीन”, मैं हर ग्रेड की कीमत दिखाऊँगा।',
