  'Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates. Contact: samelectronics.uae@gmail.com.': 'Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates. संपर्क: samelectronics.uae@gmail.com.',
  'Prices, stock, delivery times and offers depend on where you are. Please do not hide your location (for example with a VPN) when you browse or order; if you do, what you see may not apply to you and we may ask you to confirm your location before we confirm an order.': 'कीमतें, स्टॉक, डिलीवरी का समय और ऑफ़र आपकी जगह पर निर्भर करते हैं। ब्राउज़ या ऑर्डर करते समय अपनी लोकेशन न छिपाएँ (जैसे VPN से); वरना जो आप देखते हैं वह शायद आप पर लागू न हो, और ऑर्डर की पुष्टि से पहले हम आपसे लोकेशन की पुष्टि करने को कह सकते हैं।',
  'Everything on this website and in our systems (photos, designs, texts, prices and data) belongs to Sam Electronics and is protected by UAE copyright law (Federal Decree-Law No. 38 of 2021). You may keep a copy for your own reference; copying, sharing or publishing it needs our written permission.': 'इस वेबसाइट और हमारे सिस्टम की हर चीज़ (फ़ोटो, डिज़ाइन, टेक्स्ट, कीमतें और डेटा) Sam Electronics की है और यूएई कॉपीराइट क़ानून (संघीय डिक्री-क़ानून संख्या 38, 2021) से सुरक्षित है। आप अपने संदर्भ के लिए एक प्रति रख सकते हैं; कॉपी करने, साझा करने या प्रकाशित करने के लिए हमारी लिखित अनुमति ज़रूरी है।',
  'Battery (essential, always on): your cart, language, sign-in and these choices. Kept until you clear them; sign-in until you sign out.': 'बैटरी (ज़रूरी, हमेशा चालू): आपकी कार्ट, भाषा, साइन-इन और ये विकल्प। जब तक आप हटाएँ नहीं तब तक रखे जाते हैं; साइन-इन साइन-आउट तक।',
  'Memory Chip (preferences): currency, sounds, recent searches, starred parts and your devices. Kept 12 months.': 'मेमोरी चिप (पसंद): मुद्रा, आवाज़ें, हाल की खोजें, स्टार किए पार्ट्स और आपके डिवाइस। 12 महीने रखे जाते हैं।',
  'Diagnostics (anonymous statistics): which pages are opened and how fast they load, never your name or contact. Kept 13 months.': 'डायग्नोस्टिक्स (गुमनाम आँकड़े): कौन-से पेज खुलते हैं और कितनी तेज़ी से लोड होते हैं, कभी आपका नाम या संपर्क नहीं। 13 महीने रखे जाते हैं।',
  'Antenna (marketing and offers): the kinds of parts you look at, to show matching offers. Kept 6 months.': 'एंटीना (मार्केटिंग और ऑफ़र): आप किस तरह के पार्ट्स देखते हैं, ताकि मिलते-जुलते ऑफ़र दिखाए जा सकें। 6 महीने रखे जाते हैं।',
  'The banner asks once, after the welcome. Change your choice any time with "Cookie settings" at the bottom of every page, or clear everything in your browser: the site will simply forget your cart and preferences on that device. Each choice is saved with its date.': 'बैनर स्वागत के बाद सिर्फ़ एक बार पूछता है। हर पेज के नीचे "कुकी सेटिंग्स" से कभी भी अपना विकल्प बदलें, या ब्राउज़र में सब कुछ साफ़ करें: साइट उस डिवाइस पर आपकी कार्ट और पसंद भूल जाएगी। हर विकल्प तारीख के साथ सहेजा जाता है।',
  'Brand names, model names and logos (such as Apple, Samsung, Xiaomi, Huawei and others) belong to their owners. We use them only to show which phones a part fits. Sam Electronics is an independent parts seller and repair shop, and is not affiliated with, authorised by or endorsed by these brands unless a page says so.': 'ब्रांड नाम, मॉडल नाम और लोगो (जैसे Apple, Samsung, Xiaomi, Huawei और अन्य) उनके मालिकों के हैं। हम उनका उपयोग सिर्फ़ यह दिखाने के लिए करते हैं कि कोई पार्ट किन फ़ोनों में फिट होता है। Sam Electronics एक स्वतंत्र पार्ट्स विक्रेता और रिपेयर शॉप है, और जब तक कोई पेज ऐसा न कहे, इन ब्रांडों से संबद्ध, अधिकृत या समर्थित नहीं है।',
  'Every part is labelled with its quality and its maker. "Original" and "Service Pack" mean parts made for the brand; every other quality is a compatible part from the maker named on the label.': 'हर पार्ट पर उसकी क्वालिटी और निर्माता लिखा होता है। "Original" और "Service Pack" का मतलब ब्रांड के लिए बने पार्ट्स हैं; बाकी हर क्वालिटी लेबल पर लिखे निर्माता का कम्पैटिबल पार्ट है।',
