  'Most screens, cameras, back glass': 'ज़्यादातर स्क्रीन, कैमरे, बैक ग्लास',
  'Original screens on flagship phones': 'फ़्लैगशिप फ़ोनों की ओरिजिनल स्क्रीन',
  'Tell us when, we print your job card.': 'बताइए कब, हम आपका जॉब कार्ड प्रिंट करेंगे।',
  'SHIPPING ORDER': 'शिपिंग ऑर्डर',
  'Tap “Model Number” once: it changes to a code that starts with A (for example A2846).': '"मॉडल नंबर" पर एक बार टैप करें: यह A से शुरू होने वाले कोड में बदल जाएगा (जैसे A2846)।',
  'Parts, repairs, trade, shipping and payments. Search, or pick a topic. Still stuck? Samsoom is one tap away.': 'पार्ट्स, रिपेयर, ट्रेड, शिपिंग और भुगतान। खोजें या कोई विषय चुनें। अब भी उलझन? समसूम बस एक टैप दूर है।',
  'Pay your way.': 'अपने तरीके से भुगतान करें।',
  'Every way you can pay us today, in the shop, online and from abroad. Prices are in AED; card payments are charged in AED.': 'आज भुगतान के सभी तरीके, दुकान में, ऑनलाइन और विदेश से। कीमतें AED में; कार्ड भुगतान AED में लिया जाता है।',
  'Online card payments go through a secure payment page; we never see or keep your card details.': 'ऑनलाइन कार्ड भुगतान सुरक्षित भुगतान पेज से होते हैं; हम आपके कार्ड का विवरण कभी नहीं देखते या रखते।',
  'We never ask for your card number on WhatsApp or by e-mail.': 'हम व्हाट्सऐप या ई-मेल पर कभी आपका कार्ड नंबर नहीं माँगते।',
  'Need another way to pay? Ask us on WhatsApp and we will tell you what is possible.': 'भुगतान का कोई और तरीका चाहिए? व्हाट्सऐप पर पूछें, हम बताएँगे क्या संभव है।',
  'When your internet connection says you are in a different place than your device’s clock, you are most likely using a VPN or a proxy.': 'जब आपका इंटरनेट कनेक्शन आपके डिवाइस की घड़ी से अलग जगह बताता है, तो आप शायद VPN या प्रॉक्सी इस्तेमाल कर रहे हैं।',
  'Prices, stock, delivery times and offers on this website depend on where you really are. With a hidden location, what you see may not apply to you, and we may ask you to confirm your location before we confirm an order.': 'इस वेबसाइट पर कीमतें, स्टॉक, डिलीवरी समय और ऑफ़र आपकी असली जगह पर निर्भर करते हैं। छिपी लोकेशन के साथ जो आप देखते हैं वह शायद आप पर लागू न हो, और ऑर्डर की पुष्टि से पहले हम लोकेशन की पुष्टि माँग सकते हैं।',
  'Our terms of use ask visitors not to hide their location when browsing or ordering. If you are simply travelling, choose “I am travelling” and carry on: nothing else changes.': 'हमारी उपयोग की शर्तें आगंतुकों से कहती हैं कि ब्राउज़ या ऑर्डर करते समय लोकेशन न छिपाएँ। अगर आप बस यात्रा कर रहे हैं, तो "मैं यात्रा में हूँ" चुनें और जारी रखें: और कुछ नहीं बदलता।',
  'We only compare two time zones. We never store your IP address.': 'हम सिर्फ़ दो टाइम ज़ोन की तुलना करते हैं। हम कभी आपका IP पता सेव नहीं करते।',
  'Browsers can only see the screenshot keys on computers (Print Screen, ⌘⇧3/4/5, Win+Shift+S). When we see one, this notice appears once and the team is told which page it was.': 'ब्राउज़र सिर्फ़ कंप्यूटर पर स्क्रीनशॉट कीज़ देख पाते हैं (Print Screen, ⌘⇧3/4/5, Win+Shift+S)। जब हम एक देखते हैं, यह सूचना एक बार दिखती है और टीम को बताया जाता है कि कौन-सा पेज था।',
  'If you took it for another reason, you can safely ignore the notice. For permission, write to us from the Contact page.': 'अगर आपने किसी और वजह से लिया है, तो सूचना को अनदेखा कर सकते हैं। अनुमति के लिए संपर्क पेज से हमें लिखें।',
