  'Screenshots are for your own use only, for example to remember a part or to send it to your technician.': 'स्क्रीनशॉट सिर्फ़ आपके अपने इस्तेमाल के लिए हैं, जैसे कोई पार्ट याद रखने या अपने टेक्नीशियन को भेजने के लिए।',
  'Publishing, reselling or editing them, or using our photos and prices elsewhere, needs our written permission.': 'इन्हें प्रकाशित करना, दोबारा बेचना, एडिट करना या हमारी फ़ोटो और क़ीमतें कहीं और इस्तेमाल करना हमारी लिखित अनुमति से ही।',
